fun cube(n: Long): List<Long> {
  var xs: MutableList<Long> = arrayRepeating(0L, n * n * n)
  for (i in 0L ..< xs.count) {
    xs[i] = i * 2L
    xs[i] = xs[i] + 1L
  }
  return xs
}

fun histogram(words: List<String>): Map<String, Long> {
  var table: MutableMap<String, Long> = mutableMapOf<String, Long>()
  for (w in words) {
    table[w] = (table[w] ?: 0L) + 1L
  }
  return table
}

fun aliasing(ys: List<Long>): Triple<List<Long>, List<Long>, List<Long>> {
  var xs: MutableList<Long> = ys.toMutableList()
  val before = xs.toList()
  xs[0L] = 99L
  xs.bloomAppend(7L)
  val last = xs.bloomRemoveLast()
  xs.bloomInsert(last + 1L, 0L)
  return Triple(ys, before, xs.toList())
}

