}

fun grid(): Pair<List<List<Long>>, List<Long>> {
  var g: MutableList<List<Long>> = mutableListOf(listOf(0L, 0L), listOf(0L, 0L))
  val row = g[0L]
  g[0L] = g[0L].replacing(1L, 5L)
  g.bloomAppend(row)
  return Pair(g.toList(), row)
}

fun doubled(ys: List<Long>): List<Long> {
  var xs: MutableList<Long> = ys.toMutableList()
  for (x in xs.toList()) {
    xs.bloomAppend(x * 10L)
  }
  return xs
}

fun captured(): Pair<Long, List<Long>> {
  var xs: MutableList<Long> = mutableListOf<Long>()
  val add = { xs.bloomAppend(xs.count) }
  add()
  add()
  val snapshot = xs.toList()
