fun escapes(ys: List<Long>): List<List<Long>> {
  var xs: MutableList<Long> = ys.toMutableList()
  xs[0L] = xs[0L] + 1L
  var g: MutableList<List<Long>> = mutableListOf(xs.toList())
  g[0L] = g[0L].replacing(0L, 2L)
  val f = { xs.toList() }
  return listOf(xs.toList(), f(), g[0L])
}

fun bump(n: InOut<Long>) {
  n.value = n.value + 1L
}

fun fill(xs: InOut<MutableList<Long>>, with: Long) {
  val v = with
  for (i in 0L ..< xs.value.count) {
    xs.value[i] = v
  }
  xs.value.bloomAppend(v)
}

fun takeLast(xs: InOut<MutableList<Long>>): Long {
  if (xs.value.isEmpty()) {
    return 0L
  }
  return xs.value.bloomRemoveLast()
}

fun swapped(a: InOut<Long>, b: InOut<Long>) {
  val t = a.value
  a.value = b.value
  b.value = t
}

fun echo(xs: InOut<MutableList<Long>>): List<Long> {
  xs.value.bloomAppend(0L)
  return xs.value.toList()
}

